  am <- get("anova_model", envir = .envir_result)
  sm <- summary(am)
  pval <- sm[[1]]$`Pr(>F)`[1]
  if (!is.na(pval) && pval < 0.001) {
    list(correct = TRUE, type = "success", message = paste0("Overall ANOVA p = ", format(pval, digits = 3), " — species means differ."))
  } else {
    list(correct = FALSE, type = "info", message = "Fit `aov(bill_depth_mm ~ species, data = penguin_data)` and print `summary()`.")
  }
}
```
